// purrdometer-web — the dashboard over HTTP: the same history as the e-paper
// screens, read-only from the logger's database. cpp-httplib serves pages
// rendered by templates that pagec compiled into C++ (web/pages/*.page).
//
// Usage: purrdometer-web [--config PATH] [--db PATH] [--wheels PATH]
//                        [--bind ADDR] [--port N] [--check-config] [--selftest]

#include "common/calendar.h"
#include "common/ini.h"
#include "common/wheel.h"
#include "web/dashboard.h"
#include "web/html.h"
#include "web/stats.h"
#include "dashboard.page.h" // generated by pagec

#include <httplib.h>
#include <sqlite3.h>
#include <nlohmann/json.hpp>

#include <algorithm>
#include <cctype>
#include <cmath>
#include <cstdio>
#include <ctime>
#include <fstream>
#include <iostream>

namespace {

// A Pi Zero serves a handful of browsers at most.
constexpr int WORKER_THREADS = 2;

struct Settings {
    std::string db = "/var/lib/purrdometer/purrdometer.db";
    std::string config = "/etc/purrdometer/purrdometer.conf";
    std::string wheels = "/usr/share/purrdometer/wheels.ini";
    std::string bind = "0.0.0.0";
    int port = 8080;
    std::string units = purr::DEFAULT_UNITS;
    purr::Wheel wheel;
    std::vector<std::string> errors;
};

// The config file is shared with the display; docs/guide/configuration.md describes it.
void loadConfig(Settings& s, bool bindGiven, bool portGiven)
{
    purr::WheelPresets presets = purr::loadPresets(s.wheels);
    std::optional<std::string> model, diameter;
    if (auto ini = purr::Ini::load(s.config)) {
        model = ini->get("wheel", "model");
        diameter = ini->get("wheel", "diameter");
        std::string units = ini->get("wheel", "units").value_or(purr::DEFAULT_UNITS);
        std::transform(units.begin(), units.end(), units.begin(), [](unsigned char c) { return std::tolower(c); });
        if (purr::validUnits(units))
            s.units = units;
        else
            s.errors.push_back("[wheel] units must be one of cm, in, not '" + units + "'");
        if (auto b = ini->get("web", "bind"); b && !bindGiven)
            s.bind = *b;
        if (auto p = ini->get("web", "port"); p && !portGiven)
            s.port = std::stoi(*p);
    }
    try {
        s.wheel = purr::resolveWheel(presets, model, diameter, s.units);
    } catch (const std::invalid_argument& e) {
        // Keep serving on the default wheel; the page and --check-config show the error.
        s.errors.push_back(std::string("[wheel] ") + e.what());
        s.wheel = purr::resolveWheel(presets, std::nullopt, std::nullopt);
    }
}

std::string renderDashboard(const Settings& s)
{
    std::time_t now = std::time(nullptr);
    purr::Dashboard view = purr::buildDashboard(purr::loadStats(s.db, purr::cal::localDay(now)), s.wheel, now);
    view.configErrors = s.errors;
    view.units = s.units;
    std::string html;
    html.reserve(64 * 1024);
    purr::pages::dashboard(html, view);
    return html;
}

std::string renderApi(const Settings& s)
{
    std::time_t now = std::time(nullptr);
    purr::Stats st = purr::loadStats(s.db, purr::cal::localDay(now));
    const purr::Wheel& w = s.wheel;
    nlohmann::json daily = nlohmann::json::array();
    for (auto& [d, r] : st.daily)
        daily.push_back({{"date", purr::cal::iso(d)}, {"rotations", r}, {"km", w.km(r)}});
    nlohmann::json j = {
        {"wheel", {{"name", w.name}, {"diameter_m", w.diameterM}, {"circumference_m", w.circumferenceM()},
                   {"estimated", w.estimated}}},
        {"total", {{"rotations", st.total}, {"km", w.km(st.total)}}},
        {"today", {{"rotations", st.today}, {"km", w.km(st.today)}}},
        {"first_day", st.firstDay ? nlohmann::json(purr::cal::iso(*st.firstDay)) : nlohmann::json(nullptr)},
        {"live", {{"running", st.live.running(double(now))}, {"rpm", st.live.rpm}, {"kmh", w.kmh(st.live.rpm)},
                  {"connected", st.live.connected},
                  {"last_motion", st.live.lastMotion ? nlohmann::json(*st.live.lastMotion) : nlohmann::json(nullptr)},
                  {"battery", st.live.battery ? nlohmann::json(*st.live.battery) : nlohmann::json(nullptr)}}},
        {"daily", daily},
    };
    return j.dump();
}

int serve(const Settings& s)
{
    httplib::Server server;
    server.new_task_queue = [] { return new httplib::ThreadPool(WORKER_THREADS); };
    server.Get("/", [&](const httplib::Request&, httplib::Response& res) {
        res.set_content(renderDashboard(s), "text/html; charset=utf-8");
        res.set_header("Cache-Control", "no-store");
    });
    server.Get("/api/stats", [&](const httplib::Request&, httplib::Response& res) {
        res.set_content(renderApi(s), "application/json");
        res.set_header("Cache-Control", "no-store");
    });
    server.Get("/healthz", [](const httplib::Request&, httplib::Response& res) { res.set_content("ok\n", "text/plain"); });
    server.set_exception_handler([](const httplib::Request& req, httplib::Response& res, std::exception_ptr ep) {
        try {
            std::rethrow_exception(ep);
        } catch (const std::exception& e) {
            std::cerr << req.path << ": " << e.what() << std::endl;
        }
        res.status = 500;
        res.set_content("internal error\n", "text/plain");
    });
    std::cout << "serving on http://" << s.bind << ":" << s.port << "/ from " << s.db << " ("
              << purr::describe(s.wheel, s.units) << ")" << std::endl;
    if (!server.listen(s.bind, s.port)) {
        std::cerr << "cannot listen on " << s.bind << ":" << s.port << std::endl;
        return 1;
    }
    return 0;
}

int selftest(const std::string& wheelsPath, const std::string& tmpDir)
{
    int failures = 0;
    auto check = [&](bool ok, const std::string& what) {
        std::cout << (ok ? "ok   " : "FAIL ") << what << '\n';
        failures += !ok;
    };
    auto near = [](double a, double b) { return std::fabs(a - b) < 1e-4; };
    auto throws = [](auto&& f) {
        try {
            f();
        } catch (const std::invalid_argument&) {
            return true;
        }
        return false;
    };
    using namespace purr;

    for (const char* t : {"48in", "48\"", "48 inches", "121.92cm", "1219.2 mm", "1.2192m"})
        check(near(parseDiameter(t), 1.2192), std::string("diameter ") + t);
    for (const char* t : {"48ft", "5in", "", "abc", "3m"})
        check(throws([&] { parseDiameter(t); }), std::string("rejects diameter '") + t + "'");
    check(near(parseDiameter("123"), 1.23), "a bare number is cm by default");
    check(near(parseDiameter("48.5", "in"), 48.5 * INCH), "a bare number in inches when units = in");
    check(near(parseDiameter("48.5in", "cm"), 48.5 * INCH), "an explicit unit wins");
    auto hint = [](const std::string& t, const std::string& u) {
        try {
            parseDiameter(t, u);
        } catch (const std::invalid_argument& e) {
            return std::string(e.what());
        }
        return std::string();
    };
    check(hint("48.5", "cm").find("did you mean 48.5in?") != std::string::npos, "hints at inches");
    check(hint("123", "in").find("did you mean 123cm?") != std::string::npos, "hints at centimetres");
    check(throws([&] { parseLength("48"); }), "no unit and none chosen");

    WheelPresets presets = loadPresets(wheelsPath);
    check(presets.find("ferris-g5") && near(presets.find("ferris-g5")->circumferenceM(), 3.8303),
          "Ferris G5 runs on its 48\" inner diameter");
    check(presets.find("grand-ferris") && near(presets.find("grand-ferris")->diameterM, 60 * INCH), "Grand Ferris 60\"");
    check(presets.find("one-fast-cat") && near(presets.find("one-fast-cat")->diameterM, 43 * INCH), "One Fast Cat 43\"");
    check(presets.find("star-cat-xl") && presets.find("star-cat-xl")->estimated, "Star Cat inner diameters are estimates");
    Wheel measured = resolveWheel(presets, std::string("ferris-g5"), std::string("48.5in"));
    check(near(measured.diameterM, 48.5 * INCH) && measured.name.find("measured") != std::string::npos,
          "measured diameter overrides the model");
    check(resolveWheel(presets, std::nullopt, std::nullopt).key == DEFAULT_WHEEL, "default wheel");
    check(describe(*presets.find("ferris-g5")).find("running diameter 121.9 cm (48.0 in), outer 129.5 cm") !=
              std::string::npos, "sizes in cm by default");
    check(describe(*presets.find("ferris-g5"), "in").find("running diameter 48.0 in (121.9 cm), outer 51.0 in") !=
              std::string::npos, "sizes in inches when units = in");
    check(throws([&] { resolveWheel(presets, std::string("hamster-3000"), std::nullopt); }), "unknown model");

    check(cal::weekday(cal::fromIso("2026-10-26")) == 0, "2026-10-26 is a Monday");
    check(cal::iso(cal::fromIso("2024-02-29") + 1) == "2024-03-01", "leap day arithmetic");

    check(web::escape("<a href=\"x\">&'") == "&lt;a href=&quot;x&quot;&gt;&amp;&#39;", "HTML escaping");
    check(web::thousands(223867) == "223,867" && web::km(4.84) == "4.8" && web::km(857.4) == "857", "number formats");

    // A real database file through the whole page.
    std::string db = tmpDir + "/purrdometer-web-selftest.db";
    std::remove(db.c_str());
    {
        sqlite3* raw = nullptr;
        sqlite3_open(db.c_str(), &raw);
        std::time_t now = std::time(nullptr);
        std::string sql = "CREATE TABLE minutes (minute INTEGER PRIMARY KEY, revs INTEGER NOT NULL);"
                          "CREATE TABLE state (key TEXT PRIMARY KEY, value TEXT);"
                          "INSERT INTO minutes VALUES (" + std::to_string(now / 60) + ", 100), (" +
                          std::to_string(now / 60 - 3 * 1440) + ", 50);"
                          "INSERT INTO state VALUES ('connected','1'), ('rpm','54'), ('last_motion','" +
                          std::to_string(now) + "'), ('battery','85');";
        sqlite3_exec(raw, sql.c_str(), nullptr, nullptr, nullptr);
        sqlite3_close(raw);
    }
    Settings s;
    s.db = db;
    s.wheel = *presets.find("ferris-g5");
    Stats st = loadStats(db, cal::localDay(std::time(nullptr)));
    check(st.total == 150 && st.today == 100 && st.live.connected && st.live.rpm == 54, "database read");
    std::string html = renderDashboard(s);
    check(html.find("150") != std::string::npos && html.find("Running") != std::string::npos &&
              html.find("battery 85%") != std::string::npos && html.find("<polyline") != std::string::npos,
          "dashboard renders totals, live state and charts");
    auto api = nlohmann::json::parse(renderApi(s));
    check(api["total"]["rotations"] == 150 && api["daily"].size() == 2, "JSON API");
    s.db = tmpDir + "/does-not-exist.db";
    check(renderDashboard(s).find("no rotations yet") != std::string::npos, "empty database renders");
    std::remove(db.c_str());

    std::cout << (failures ? "FAILED\n" : "all passed\n");
    return failures ? 1 : 0;
}

} // namespace

int main(int argc, char** argv)
{
    Settings s;
    bool check = false, test = false, bindGiven = false, portGiven = false;
    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        auto next = [&]() -> std::string {
            if (i + 1 >= argc) {
                std::cerr << a << " needs a value\n";
                std::exit(2);
            }
            return argv[++i];
        };
        if (a == "--config") s.config = next();
        else if (a == "--db") s.db = next();
        else if (a == "--wheels") s.wheels = next();
        else if (a == "--bind") { s.bind = next(); bindGiven = true; }
        else if (a == "--port") { s.port = std::stoi(next()); portGiven = true; }
        else if (a == "--check-config") check = true;
        else if (a == "--selftest") test = true;
        else {
            std::cerr << "usage: purrdometer-web [--config PATH] [--db PATH] [--wheels PATH] [--bind ADDR] [--port N]"
                         " [--check-config] [--selftest]\n";
            return 2;
        }
    }
    try {
        if (test) {
            const char* tmp = std::getenv("PURR_TMP");
            return selftest(s.wheels, tmp ? tmp : "tmp");
        }
        loadConfig(s, bindGiven, portGiven);
        if (check) {
            std::cout << s.config << ": " << purr::describe(s.wheel, s.units) << "\n";
            for (auto& e : s.errors)
                std::cerr << "error: " << e << "\n";
            return s.errors.empty() ? 0 : 1;
        }
        return serve(s);
    } catch (const std::exception& e) {
        std::cerr << "fatal: " << e.what() << std::endl;
        return 1;
    }
}
